$ErrorActionPreference='Stop'
$inputPath='C:\Users\akhil\Downloads\FixKart_Master_Test_Cases_1250.csv'
$root='C:\Users\akhil\OneDrive\Desktop\Workspace\fixkart\plumbing-qcommerce\plumbing-qcommerce'
$outDir=Join-Path $root 'reports\local-1250-20260928-fixed'
New-Item -ItemType Directory -Force -Path (Join-Path $outDir 'browser-evidence') | Out-Null
$rows=@(Import-Csv $inputPath); $ts=(Get-Date).ToString('o')
$pass=@{
 'FK-PLB-AUTH-LGN-002'=@('Plumber empty login validation','browser-evidence/BROWSER-PLB-001.png');
 'FK-STR-AUTH-LGN-002'=@('Store empty login validation','browser-evidence/BROWSER-STORE-001.png')
}
$results=foreach($row in $rows){
 $id=$row.'Test ID'; $hist=$row.'Execution status'
 if($hist -eq 'N/A'){$status='N/A';$actual='Not applicable according to the supplied inventory.';$def='';$sev='';$pri='';$blocked=''}
 elseif($pass.ContainsKey($id)){$status='PASS';$actual='Visible local browser flow completed. Empty login submission displayed the expected validation state on the rendered UI.';$def='';$sev='';$pri='';$blocked=''}
 else{$status='NOT TESTED';$actual='The local stack was repaired and smoke-tested, but this case-specific browser flow was not executed in this run; no PASS or FAIL was inferred.';$def='EXEC-LOCAL-001';$sev='Medium';$pri='P2';$blocked='Case-specific manual browser execution remains outstanding.'}
 $evidence=if($pass.ContainsKey($id)){$pass[$id][1]}else{'browser-evidence/browser-smoke.json'}
 [pscustomobject]@{'Test ID'=$id;Application=$row.Application;Module=$row.Module;Feature=$row.Feature;'Scenario title'=$row.'Scenario title';Preconditions=$row.Preconditions;'Steps executed'=if($pass.ContainsKey($id)){$pass[$id][0]}else{'Not executed; recorded explicitly as NOT TESTED'};'Expected result'=$row.'Expected result';'Actual result'=$actual;Status=$status;'Defect ID'=$def;Severity=$sev;Priority=$pri;'Evidence screenshot/reference'=$evidence;'Console/network evidence'='browser-evidence/browser-smoke.json';'Deployment/source commit'='80f14c898db7fec4c750462273b0aacd5bc9b2d2';Timestamp=$ts;'Historical status'=$hist;'Blocked reason'=$blocked;Notes='Current-run result; supplied historical execution status was not reused as evidence.'}
}
$csv=Join-Path $outDir 'FixKart_Master_Test_Cases_1250_LOCAL_EXECUTION_20260928_FIXED.csv';$results|Export-Csv -NoTypeInformation -Encoding UTF8 $csv
$dupes=@($rows|Group-Object 'Test ID'|? Count -gt 1);$counts=$results|Group-Object Status|Sort Name
$summary=@('# FixKart local 1,250-case execution report - post-fix','',"Input: $inputPath","Rows: $($rows.Count)","Unique IDs: $(@($rows.'Test ID'|Select -Unique).Count)","Duplicate ID groups: $($dupes.Count)",'','## Result totals','', '| Status | Count |','|---|---|');foreach($c in $counts){$summary+="| $($c.Name) | $($c.Count) |"};$summary+=@('','## Root-cause fix','', 'Recreated the detached backend container on the Compose network, enabled the local-staging profile and local seed/SMS settings, corrected SeedProperties validation for staging, aligned the Kafka default contract, and made V23 migration timestamp types H2-compatible.','', '## Interpretation','', 'Only cases with case-specific visible browser evidence are PASS. The remaining non-N/A IDs are explicitly NOT TESTED, not silently passed.');$summary|Set-Content -Encoding UTF8 (Join-Path $outDir 'EXECUTIVE_SUMMARY.md')
$ev=@('# Browser/local evidence','',"Timestamp: $ts",'', '- Customer: landing/onboarding rendered at http://localhost:8092; no failed requests; one React Native animation warning.', '- Plumber: login rendered at http://localhost:8093; empty Continue displayed mobile validation; no console errors or failed requests.', '- Store: login rendered at http://localhost:8094; empty submit flow remained on login; no failed requests; one animation warning.', '- Admin: login rendered at http://localhost:3100; no console errors or failed requests.', '- Backend readiness: HTTP 200 at localhost:8081/health/ready.');$ev|Set-Content -Encoding UTF8 (Join-Path $outDir 'BROWSER_AND_LOCAL_EVIDENCE.md')
$def=@([pscustomobject]@{DefectID='EXEC-LOCAL-001';Application='Cross-App';Module='Manual execution';Summary='1,238 non-N/A canonical cases were not executed case-by-case in this run';Severity='Medium';Priority='P2';Status='OPEN';Evidence='FixKart_Master_Test_Cases_1250_LOCAL_EXECUTION_20260928_FIXED.csv';Notes='Explicitly not tested; no PASS inferred.'});$def|Export-Csv -NoTypeInformation -Encoding UTF8 (Join-Path $outDir 'DEFECT_REGISTER.csv')
$results|Select 'Test ID',Application,Module,'Scenario title',Status,'Defect ID','Historical status'|ConvertTo-Html -Title 'FixKart Local 1,250 Case Report'|Set-Content -Encoding UTF8 (Join-Path $outDir 'DETAILED_REPORT.xls')
(@('# Deployment and source verification','', '- Local source commit: 80f14c898db7fec4c750462273b0aacd5bc9b2d2', '- origin/Development: 93fb9f2dc8436956b4b3f4e2c23429cb8d699729', '- origin/Development-2: 80f14c898db7fec4c750462273b0aacd5bc9b2d2', '- Local run target: repaired local Docker/Expo export stack', '- Live deployment code parity: not asserted; live deployment commit metadata remains separate from this local run.','', '## Automated verification','', '- Frontend typechecks: Customer, Plumber, Store, Admin passed.', '- Frontend unit tests: Customer 8, Plumber 10, Store 13, Admin 2, Edge 16 passed.', '- Backend targeted regression tests passed after fixes.', '- Backend full suite was rerun; see tmp/backend-full-postfix.log.')) | Set-Content -Encoding UTF8 (Join-Path $outDir 'DEPLOYMENT_VERIFICATION_REPORT.md')
Write-Output "Generated $($results.Count) rows; duplicate groups=$($dupes.Count)"
